/**
 * Content model for the MMO anode product family pages.
 *
 * Every page in the family shares one block vocabulary, so a single renderer
 * (`src/components/mmo/MmoProductPage.astro`) can present all of them.
 * Copy is transcribed from the product pages this site mirrors; images are
 * local copies under `/images/titanium-anode/`.
 */

export interface MmoImage {
  src: string;
  alt: string;
}

export interface MmoCta {
  label: string;
  href: string;
}

export interface MmoStat {
  value: string;
  label: string;
}

export interface MmoAnchor {
  label: string;
  href: string;
}

export interface MmoListItem {
  title: string;
  paras: string[];
  list?: string[];
}

export interface MmoImageListItem extends MmoListItem {
  image: MmoImage;
  index?: string;
}

export interface MmoCardItem extends MmoListItem {
  index?: string;
}

export interface MmoFaqItem {
  q: string;
  a: string;
}

export type MmoBlock =
  | { kind: 'items'; items: MmoListItem[] }
  | { kind: 'cards'; items: MmoCardItem[] }
  | { kind: 'imageCards'; items: MmoImageListItem[] }
  | { kind: 'table'; header: string[]; rows: string[][]; dark?: boolean }
  | { kind: 'list'; items: string[] }
  | { kind: 'faq'; items: MmoFaqItem[] }
  | { kind: 'pills'; items: string[] }
  | { kind: 'paragraphs'; texts: string[] }
  | { kind: 'note'; label: string; paras: string[] }
  | { kind: 'subheading'; eyebrow: string; text: string }
  | { kind: 'label'; text: string }
  | { kind: 'button'; label: string; href: string }
  | { kind: 'link'; text: string; href: string }
  | { kind: 'figure'; image: MmoImage };

export type MmoTone = 'plain' | 'alt' | 'navy' | 'dark';

export interface MmoSection {
  id: string;
  /** The classes of the section element itself — the band it sits on. */
  cls: string;
  /** The body of the section, in the markup of the reference page. */
  html: string;
  /** The text of the section, for the search index and the JSON-LD. */
  eyebrow: string;
  title: string;
  tone: MmoTone;
  lead: string;
}

export interface MmoForm {
  /** Submit label of the inquiry form. */
  button: string;
}

export interface MmoRfq {
  eyebrow: string;
  title: string;
  intro: string;
  checklist: string[];
  emailLabel: string;
  email: string;
  address: string;
}

export interface MmoPage {
  slug: string;
  name: string;
  seoTitle: string;
  description: string;
  /** The hero of the page, in the markup of the reference page. */
  heroHtml: string;
  /** The anchor navigation that sits under the hero. */
  navHtml: string;
  /** The request for a quote, in the markup of the reference page. */
  rfqHtml: string;
  anchorNav: MmoAnchor[];
  sections: MmoSection[];
  form: MmoForm;
  rfq: MmoRfq;
}

