        cls: 'py-20 lg:py-24 bg-slate-50 border-b border-slate-200',
        html: '\n        <div class="w-full max-w-7xl mx-auto px-5 sm:px-6 lg:px-8" data-mmo-container="page">\n            <div class="text-center mb-12 lg:mb-16">\n                <span class="text-blue-600 font-bold tracking-wider uppercase text-sm mb-3 block">FREQUENTLY ASKED QUESTIONS</span>\n                <h2 class="text-3xl md:text-4xl font-bold text-slate-900 mb-4">MMO Ribbon Anode FAQs</h2>\n            </div>\n\n            <div class="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6 items-start">\n                \n                <details class="group bg-white rounded-2xl shadow-sm border border-slate-200 transition-all duration-300">\n                    <summary class="p-5 text-lg font-semibold text-slate-800 cursor-pointer list-none flex justify-between items-center [&amp;::-webkit-details-marker]:hidden">\n                        What is an MMO ribbon anode?\n                        <svg class="w-5 h-5 group-open:rotate-180 transition-transform duration-300 shrink-0 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>\n                    </summary>\n                    <div class="px-5 pb-5 text-slate-600 leading-relaxed">\n                        An MMO ribbon anode is a solid flat titanium ribbon coated with mixed metal oxide and used as an active electrode in distributed impressed-current cathodic-protection systems.\n                    </div>\n                </details>\n\n                \n                <details class="group bg-white rounded-2xl shadow-sm border border-slate-200 transition-all duration-300">\n                    <summary class="p-5 text-lg font-semibold text-slate-800 cursor-pointer list-none flex justify-between items-center [&amp;::-webkit-details-marker]:hidden">\n                        Is MMO ribbon the same as MMO mesh ribbon?\n                        <svg class="w-5 h-5 group-open:rotate-180 transition-transform duration-300 shrink-0 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>\n                    </summary>\n                    <div class="px-5 pb-5 text-slate-600 leading-relaxed">\n                        No. Solid MMO ribbon uses a continuous flat strip geometry, while MMO mesh ribbon has an open mesh structure. They should be specified as separate anode forms.\n                    </div>\n                </details>\n\n                \n                <details class="group bg-white rounded-2xl shadow-sm border border-slate-200 transition-all duration-300">\n                    <summary class="p-5 text-lg font-semibold text-slate-800 cursor-pointer list-none flex justify-between items-center [&amp;::-webkit-details-marker]:hidden">\n                        Where are solid MMO ribbon anodes commonly used?\n                        <svg class="w-5 h-5 group-open:rotate-180 transition-transform duration-300 shrink-0 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>\n                    </summary>\n                    <div class="px-5 pb-5 text-slate-600 leading-relaxed">\n                        They are commonly reviewed for storage tank bottom and under-tank ICCP grid systems where parallel ribbon runs distribute protection current beneath the tank bottom.\n                    </div>\n                </details>\n\n                \n                <details class="group bg-white rounded-2xl shadow-sm border border-slate-200 transition-all duration-300">\n                    <summary class="p-5 text-lg font-semibold text-slate-800 cursor-pointer list-none flex justify-between items-center [&amp;::-webkit-details-marker]:hidden">\n                        What is the role of the titanium conductor bar?\n                        <svg class="w-5 h-5 group-open:rotate-180 transition-transform duration-300 shrink-0 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>\n                    </summary>\n                    <div class="px-5 pb-5 text-slate-600 leading-relaxed">\n                        The titanium conductor bar electrically interconnects multiple ribbon runs and forms part of the grid current-distribution network.\n                    </div>\n                </details>\n\n                \n                <details class="group bg-white rounded-2xl shadow-sm border border-slate-200 transition-all duration-300">\n                    <summary class="p-5 text-lg font-semibold text-slate-800 cursor-pointer list-none flex justify-between items-center [&amp;::-webkit-details-marker]:hidden">\n                        What determines MMO ribbon spacing?\n                        <svg class="w-5 h-5 group-open:rotate-180 transition-transform duration-300 shrink-0 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>\n                    </summary>\n                    <div class="px-5 pb-5 text-slate-600 leading-relaxed">\n                        Ribbon spacing depends on tank geometry, protection-current demand, backfill or sand condition, resistivity, grid configuration and the required current-distribution pattern.\n                    </div>\n                </details>\n\n                \n                <details class="group bg-white rounded-2xl shadow-sm border border-slate-200 transition-all duration-300">\n                    <summary class="p-5 text-lg font-semibold text-slate-800 cursor-pointer list-none flex justify-between items-center [&amp;::-webkit-details-marker]:hidden">\n                        What information is required for a quotation?\n                        <svg class="w-5 h-5 group-open:rotate-180 transition-transform duration-300 shrink-0 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="24" height="24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"></path></svg>\n                    </summary>\n                    <div class="px-5 pb-5 text-slate-600 leading-relaxed">\n                        Provide the tank diameter, bottom configuration, backfill condition, resistivity where available, required CP current, ribbon size or spacing, conductor-bar layout, design-life requirement, quantity and project drawing.\n                    </div>\n                </details>\n            </div>\n        </div>\n    ',
