    rfqHtml: '\n  <div data-mmo-container="page" class="grid gap-14 lg:grid-cols-2 lg:items-start">\n    <div><p class="text-sm font-extrabold uppercase tracking-[.16em] text-blue-300">Engineering RFQ</p><h2 class="mt-4 text-3xl font-extrabold tracking-tight sm:text-4xl">Request a Custom MMO Mesh Ribbon Anode Review</h2><p class="mt-6 text-lg leading-8 text-slate-300">Describe the concrete structure, protection or repair zone, resistivity and chloride condition, required current, mesh spacing and conductor-bar arrangement. A drawing is especially useful for verifying coverage and connections.</p><ul class="mt-8 space-y-4 text-slate-200"><li>✓ Concrete structure and treatment area</li><li>✓ Concrete resistivity and chloride condition</li><li>✓ Required current and interface current density</li><li>✓ Mesh width, opening and spacing</li><li>✓ Conductor bars, connections and embedment</li><li>✓ Design life, quantity and documentation</li></ul><div class="mt-10 border-t border-slate-800 pt-8"><p class="text-sm text-slate-400">Prefer email?</p><a href="mailto:sales@titanium-parts.com" class="mt-2 block text-lg font-semibold text-white">sales@titanium-parts.com</a><p class="mt-3 text-sm text-slate-500">Titanium Valley, Baoji City, Shaanxi Province, China</p></div></div>\n    <div class="rounded-3xl bg-white p-6 text-slate-900 shadow-2xl sm:p-8 lg:p-10">\n      <!--RFQ_FORM-->\n    </div>\n  </div>\n',
