        html: '\n    <div class="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" data-mmo-container="page">\n        <div class="max-w-3xl mb-12">\n            <div class="text-sm font-bold text-blue-600 uppercase tracking-wider mb-3">CANISTER CONSTRUCTION</div>\n            <h2 class="text-3xl md:text-[36px] font-bold text-slate-900 leading-[1.25] mb-6">What Is Inside an MMO Canister Anode?</h2>\n            <p class="text-lg text-slate-700 leading-[1.65]">\n                An MMO canister anode is a prepackaged impressed-current anode assembly in which an MMO-coated titanium active element is installed inside a canister with conductive backfill, cable connection and protected electrical termination.\n            </p>\n        </div>\n\n        <div class="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">\n            <div class="bg-white rounded-2xl border border-slate-200 p-8 flex items-center justify-center h-full min-h-[400px]">\n                <img src="/images/titanium-anode/mmo-canister-anode-mmo-canister-anode1.webp" alt="MMO canister anode internal assembly with active element and backfill" width="600" height="600" class="w-full h-full max-h-[500px] object-contain" loading="lazy" decoding="async">\n            </div>\n            \n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-6">\n                <div class="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">\n                    <h3 class="text-xl font-bold text-slate-900 mb-3">MMO Active Element</h3>\n                    <p class="text-base text-slate-700 leading-[1.65]">Provides the electrochemically active surface for impressed-current discharge. our current product range includes solid-stick and tubular internal-element configurations.</p>\n                </div>\n                <div class="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">\n                    <h3 class="text-xl font-bold text-slate-900 mb-3">Conductive Backfill</h3>\n                    <p class="text-base text-slate-700 leading-[1.65]">Carbonaceous backfill surrounds the active element and provides a controlled conductive environment inside the packaged assembly.</p>\n                </div>\n                <div class="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">\n                    <h3 class="text-xl font-bold text-slate-900 mb-3">Canister Housing</h3>\n                    <p class="text-base text-slate-700 leading-[1.65]">Contains the active element and backfill as one assembly for transportation, handling and groundbed installation.</p>\n                </div>\n                <div class="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">\n                    <h3 class="text-xl font-bold text-slate-900 mb-3">Cable &amp; Sealed Connection</h3>\n                    <p class="text-base text-slate-700 leading-[1.65]">Provides the electrical path from the active anode element to the ICCP system while protecting the connection area according to the project design.</p>\n                </div>\n            </div>\n        </div>\n        \n        <div class="mt-10 bg-white border border-slate-200 rounded-xl p-5 text-center shadow-sm">\n            <p class="text-base font-semibold text-slate-800 tracking-wide">\n                MMO Element · Carbonaceous Backfill · Canister · Cable · Seal · Identification\n            </p>\n        </div>\n    </div>\n',
