        html: '\n    <div class="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" data-mmo-container="page">\n        <div class="text-center max-w-3xl mx-auto mb-16 md:mb-20">\n            <div class="text-sm font-semibold text-blue-600 uppercase tracking-widest mb-4">Groundbed Application</div>\n            <h2 class="text-3xl md:text-4xl font-bold text-slate-900 leading-tight mb-6">Deep vs Shallow Groundbed Applications</h2>\n            <p class="text-base md:text-lg text-slate-600 leading-relaxed">\n                Canister anodes can be configured for deep or shallow impressed-current groundbeds. Final selection depends on required current, soil resistivity, available installation area, installation depth, cable routing and the complete cathodic-protection design.\n            </p>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-10 max-w-5xl mx-auto">\n            \n            <div class="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_8px_30px_-4px_rgba(0,0,0,0.1)] transition-all duration-300 flex flex-col h-full group">\n                <div class="aspect-[16/9] relative overflow-hidden bg-slate-100">\n                    <img src="/images/titanium-anode/mmo-canister-anode-deep-groundbed-installation.webp" alt="MMO canister anode for deep groundbed cathodic protection" width="600" height="338" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 ease-out" loading="lazy" decoding="async">\n                </div>\n                <div class="p-8 md:p-10 flex flex-col flex-grow">\n                    <h3 class="text-2xl font-bold text-slate-900 mb-4">Deep Groundbed Installation</h3>\n                    <p class="text-base text-slate-600 leading-relaxed mb-8 flex-grow">\n                        Used where one or more canister anodes are installed at depth as part of an engineered ICCP groundbed configuration.\n                    </p>\n                    <div class="bg-slate-50/80 p-5 rounded-2xl border border-slate-100/50">\n                        <span class="text-xs font-bold text-blue-600 uppercase tracking-wider block mb-2">Key Review</span>\n                        <span class="text-sm md:text-base text-slate-800 font-medium leading-snug block">Bore Depth · Soil Layers · Resistivity · Total Current · Cable Length</span>\n                    </div>\n                </div>\n            </div>\n\n            \n            <div class="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_8px_30px_-4px_rgba(0,0,0,0.1)] transition-all duration-300 flex flex-col h-full group">\n                <div class="aspect-[16/9] relative overflow-hidden bg-slate-100">\n                    <img src="/images/titanium-anode/mmo-canister-anode-shallow-groundbed-installation.webp" alt="MMO canister anode for shallow groundbed installation" width="600" height="338" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 ease-out" loading="lazy" decoding="async">\n                </div>\n                <div class="p-8 md:p-10 flex flex-col flex-grow">\n                    <h3 class="text-2xl font-bold text-slate-900 mb-4">Shallow Groundbed Installation</h3>\n                    <p class="text-base text-slate-600 leading-relaxed mb-8 flex-grow">\n                        Used where canister anodes are installed at shallower depth or distributed across the available protection area according to the project layout.\n                    </p>\n                    <div class="bg-slate-50/80 p-5 rounded-2xl border border-slate-100/50">\n                        <span class="text-xs font-bold text-blue-600 uppercase tracking-wider block mb-2">Key Review</span>\n                        <span class="text-sm md:text-base text-slate-800 font-medium leading-snug block">Spacing · Burial Depth · Soil Resistivity · Number of Anodes · Current Distribution</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <div class="mt-16 max-w-4xl mx-auto">\n            <div class="bg-blue-50/50 rounded-2xl p-6 md:p-8 text-center border border-blue-100/50" data-morank-theme-border="primary">\n                <p class="text-base md:text-lg text-slate-700">\n                    <strong class="text-slate-900 font-semibold">Engineering Note:</strong> Deep versus shallow groundbed selection should be determined by the cathodic-protection system design rather than by canister size alone.\n                </p>\n            </div>\n        </div>\n    </div>\n',
