    heroHtml: '\n  <div data-mmo-container="page" class="py-16 sm:py-20 lg:py-24">\n    <div class="grid gap-12 lg:grid-cols-[minmax(0,1.05fr)_minmax(420px,.95fr)] lg:items-center">\n      <div class="max-w-3xl">\n        <p class="eyebrow">MMO Tubular Anode Manufacturer · ICCP Systems</p>\n        <h1 class="mt-5 text-4xl font-extrabold leading-[1.06] tracking-tight text-slate-950 sm:text-5xl lg:text-[3.5rem]">MMO-Coated Titanium Tubular Anodes for ICCP Systems</h1>\n        <p class="mt-7 text-lg leading-8 text-slate-600 sm:text-xl">We manufacture bare, cable-connected, string and canister-ready MMO tubular anodes. Tube geometry, active coated area, environment, current-density basis, cable connection and sealing are reviewed together for the required ICCP duty.</p>\n        <div class="mt-9 flex flex-col gap-3 sm:flex-row"><a href="#rfq" class="inline-flex min-h-12 items-center justify-center rounded-xl bg-blue-600 px-7 py-3.5 text-sm font-bold text-white hover:bg-blue-700">Request Product Review</a><a href="#technical-specifications" class="inline-flex min-h-12 items-center justify-center rounded-xl border border-slate-300 bg-white px-7 py-3.5 text-sm font-bold text-slate-800 hover:border-blue-500 hover:text-blue-700">View Technical Data</a></div>\n        <div class="mt-7 border-l-4 border-blue-600 pl-5"><p class="text-sm leading-6 text-slate-600"><strong>Engineering boundary:</strong> The same tube does not carry one universal rating. Rated output must remain linked to active area, coating, electrolyte or backfill, temperature, operating duty and design-life basis.</p></div>\n      </div>\n      <div>\n        <figure class="overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-soft"><img src="/images/titanium-anode/mmo-tubular-anode-mmo-tubular-anodes1.webp" alt="MMO Tubular Anode supplied by our factory" class="aspect-[4/3] w-full object-cover" fetchpriority="high" decoding="async" loading="eager"></figure>\n        <div class="mt-4 grid grid-cols-3 gap-3"><figure class="overflow-hidden rounded-xl border border-slate-200 bg-white"><img src="/images/titanium-anode/mmo-tubular-anode-mmo-coated-titanium-tubular-anodes.webp" alt="MMO Tubular Anode product, structure or application reference" class="aspect-[4/3] w-full object-cover" loading="lazy" decoding="async"></figure><figure class="overflow-hidden rounded-xl border border-slate-200 bg-white"><img src="/images/titanium-anode/mmo-tubular-anode-mmo-coated-titanium-tubular-anodes2.webp" alt="MMO Tubular Anode product, structure or application reference" class="aspect-[4/3] w-full object-cover" loading="lazy" decoding="async"></figure><figure class="overflow-hidden rounded-xl border border-slate-200 bg-white"><img src="/images/titanium-anode/mmo-tubular-anode-mmo-coated-titanium-tubular-anodes3.webp" alt="MMO Tubular Anode product, structure or application reference" class="aspect-[4/3] w-full object-cover" loading="lazy" decoding="async"></figure></div>\n      </div>\n    </div>\n    <div class="mt-12 grid overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-soft sm:grid-cols-2 lg:grid-cols-4"><div class="border-b border-slate-200 p-5 sm:border-r lg:border-b-0"><strong class="block text-2xl text-slate-950">Ø16–Ø50 mm</strong><span class="mt-1 block text-sm text-slate-500">Reference tube diameters</span></div><div class="border-b border-slate-200 p-5 sm:border-r lg:border-b-0"><strong class="block text-2xl text-slate-950">500–1524 mm</strong><span class="mt-1 block text-sm text-slate-500">Reference lengths</span></div><div class="border-b border-slate-200 p-5 sm:border-r lg:border-b-0"><strong class="block text-2xl text-slate-950">Bare / Cable</strong><span class="mt-1 block text-sm text-slate-500">Assembly directions</span></div><div class="border-b border-slate-200 p-5 sm:border-r lg:border-b-0"><strong class="block text-2xl text-slate-950">Soil to Seawater</strong><span class="mt-1 block text-sm text-slate-500">Environment-specific ratings</span></div></div>\n  </div>\n',
