    rfqHtml: '\n  <div data-mmo-container="page" class="grid gap-14 lg:grid-cols-2 lg:items-start">\n    <div><p class="text-sm font-extrabold uppercase tracking-[.16em] text-blue-300">Engineering RFQ</p><h2 class="mt-4 text-3xl font-extrabold tracking-tight sm:text-4xl">Request a Custom MMO Tubular Anode Review</h2><p class="mt-6 text-lg leading-8 text-slate-300">Share the environment, current requirement, preferred tube geometry, active length, cable and installation arrangement. If a model is not yet selected, provide the CP duty and available installation envelope.</p><ul class="mt-8 space-y-4 text-slate-200"><li>✓ Protected structure and environment</li><li>✓ Required current or current-density basis</li><li>✓ Tube OD, wall, total and active length</li><li>✓ Bare, cable-connected, string or canister configuration</li><li>✓ Cable, end cap, seal and mounting</li><li>✓ Design life, quantity and documentation</li></ul><div class="mt-10 border-t border-slate-800 pt-8"><p class="text-sm text-slate-400">Prefer email?</p><a href="mailto:sales@titanium-parts.com" class="mt-2 block text-lg font-semibold text-white">sales@titanium-parts.com</a><p class="mt-3 text-sm text-slate-500">Titanium Valley, Baoji City, Shaanxi Province, China</p></div></div>\n    <div class="rounded-3xl bg-white p-6 text-slate-900 shadow-2xl sm:p-8 lg:p-10">\n      <!--RFQ_FORM-->\n    </div>\n  </div>\n',
