        cls: 'w-full bg-gray-50 pt-16 pb-20 border-t border-gray-100',
        html: '\n    <div data-mmo-container="page" class="w-full max-w-7xl mx-auto px-5 sm:px-6 lg:px-8">\n        <div class="max-w-3xl mb-12">\n            <span class="text-sm font-semibold tracking-wider uppercase text-blue-600 mb-2 block">PRODUCT CONFIGURATION</span>\n            <h2 class="text-3xl md:text-4xl font-bold text-gray-900 leading-tight mb-4">MMO Rod Anode Configurations</h2>\n            <p class="text-base md:text-lg text-gray-600 leading-relaxed">\n                An MMO rod anode uses a solid titanium rod as the rigid active-electrode substrate. Connection, termination and mounting can be configured according to how the electrode will be integrated into the ICCP or industrial electrochemical system.\n            </p>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-10">\n            \n            <div class="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col overflow-hidden group">\n                <div class="w-full h-56 bg-gray-50 overflow-hidden">\n                    <img src="/images/titanium-anode/mmo-rod-anode-mmo-rod-anode4.webp" alt="Standard MMO Rod Anode" width="400" height="300" class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" decoding="async" loading="lazy">\n                </div>\n                <div class="p-6 flex flex-col flex-grow border-t border-gray-50">\n                    <h3 class="text-xl font-semibold text-gray-900 mb-3">Standard MMO Rod Anode</h3>\n                    <p class="text-base text-gray-600 leading-relaxed flex-grow">\n                        Solid MMO-coated titanium rod supplied as the active electrode for compact ICCP, equipment or industrial electrochemical integration.\n                    </p>\n                </div>\n            </div>\n            \n            <div class="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col overflow-hidden group">\n                <div class="w-full h-56 bg-gray-50 overflow-hidden">\n                    <img src="/images/titanium-anode/mmo-rod-anode-mmo-rod-anode3.webp" alt="Threaded MMO Rod Anode" width="400" height="300" class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" decoding="async" loading="lazy">\n                </div>\n                <div class="p-6 flex flex-col flex-grow border-t border-gray-50">\n                    <h3 class="text-xl font-semibold text-gray-900 mb-3">Threaded MMO Rod Anode</h3>\n                    <p class="text-base text-gray-600 leading-relaxed flex-grow">\n                        Rod anode with a threaded end, nut, terminal or project-specific mechanical connection for direct equipment or fixture integration.\n                    </p>\n                </div>\n            </div>\n            \n            <div class="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col overflow-hidden group">\n                <div class="w-full h-56 bg-gray-50 overflow-hidden">\n                    <img src="/images/titanium-anode/mmo-rod-anode-mmo-rod-anode1.webp" alt="Cable-Connected MMO Rod Anode" width="400" height="300" class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" decoding="async" loading="lazy">\n                </div>\n                <div class="p-6 flex flex-col flex-grow border-t border-gray-50">\n                    <h3 class="text-xl font-semibold text-gray-900 mb-3">Cable-Connected MMO Rod Anode</h3>\n                    <p class="text-base text-gray-600 leading-relaxed flex-grow">\n                        MMO-coated rod supplied with cable connection, sealing, strain relief or project-specific termination where a ready-to-connect assembly is required.\n                    </p>\n                </div>\n            </div>\n            \n            <div class="bg-white rounded-2xl shadow-sm border border-gray-100 flex flex-col overflow-hidden group">\n                <div class="w-full h-56 bg-gray-50 overflow-hidden">\n                    <img src="/images/titanium-anode/mmo-rod-anode-custom-mmo-rod.webp" alt="Custom MMO Rod Anode Assembly" width="400" height="300" class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" decoding="async" loading="lazy">\n                </div>\n                <div class="p-6 flex flex-col flex-grow border-t border-gray-50">\n                    <h3 class="text-xl font-semibold text-gray-900 mb-3">Custom MMO Rod Anode Assembly</h3>\n                    <p class="text-base text-gray-600 leading-relaxed flex-grow">\n                        Drawing-based rod assemblies with project-specific diameter, length, active coated area, connection, mounting structure, packing and documentation.\n                    </p>\n                </div>\n            </div>\n        </div>\n\n        \n        <div class="bg-blue-50 border border-blue-100 rounded-xl p-5 flex flex-col sm:flex-row items-start sm:items-center gap-4">\n            <div class="flex-shrink-0 w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-600">\n                <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>\n            </div>\n            <div class="flex-grow">\n                <p class="text-base text-gray-700">\n                    <strong class="font-semibold text-gray-900">Engineering Note:</strong> MMO Rod Anode uses a solid titanium rod substrate. MMO Tubular Anode uses a hollow titanium tube substrate. The two forms have different geometry, active area, mechanical structure and installation options. <a href="/titanium-anode/mmo-anode/mmo-tubular-anode" class="text-blue-600 font-semibold hover:underline ml-1">View MMO Tubular Anode →</a>\n                </p>\n            </div>\n        </div>\n    </div>\n',
