        html: '\n    <div data-mmo-container="page" class="w-full max-w-7xl mx-auto px-5 sm:px-6 lg:px-8">\n        <div class="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">\n            <div>\n                <span class="text-sm font-semibold tracking-wider uppercase text-blue-600 mb-2 block">ROD SPECIFICATION</span>\n                <h2 class="text-3xl md:text-4xl font-bold text-gray-900 leading-tight mb-4">Rod Diameter, Active Length &amp; Titanium Substrate</h2>\n                <p class="text-base md:text-lg text-gray-600 leading-relaxed mb-8">\n                    Rod diameter and active coated length define the exposed cylindrical geometry of the active electrode and should be reviewed together with active surface area, electrical duty, connection design and installation requirements.\n                </p>\n                \n                <div class="bg-white border border-gray-200 rounded-2xl overflow-hidden shadow-sm">\n                    <table class="w-full text-left border-collapse">\n                        <tbody class="text-base text-gray-700">\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold w-1/3">Product</th>\n                                <td class="py-4 px-5">MMO-Coated Titanium Rod Anode</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Substrate</th>\n                                <td class="py-4 px-5">Titanium Rod</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Geometry</th>\n                                <td class="py-4 px-5">Solid Cylindrical Rod</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Reference Diameters</th>\n                                <td class="py-4 px-5">6.35 mm · 12.7 mm · 19 mm · 25 mm</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Custom Sizes</th>\n                                <td class="py-4 px-5">Available according to project requirements</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Active Coated Length</th>\n                                <td class="py-4 px-5">Project-specific</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Material Standard</th>\n                                <td class="py-4 px-5">According to confirmed order requirement / MTC</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Titanium Grade</th>\n                                <td class="py-4 px-5">According to confirmed order requirement</td>\n                            </tr>\n                            <tr class="border-b border-gray-100">\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Connection Options</th>\n                                <td class="py-4 px-5">Bare · Threaded · Cable-Connected · Terminal / Custom Assembly</td>\n                            </tr>\n                            <tr>\n                                <th class="py-4 px-5 bg-gray-50 font-semibold">Design-Life Reference</th>\n                                <td class="py-4 px-5">20 years under the confirmed rated design conditions</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            \n            <div class="relative w-full h-full min-h-[400px] bg-gray-50 rounded-2xl border border-gray-100 overflow-hidden flex items-center justify-center p-8">\n                <img src="/images/titanium-anode/mmo-rod-anode-mmo-rod-anode-hele-titanium.webp" alt="Multiple MMO coated titanium rod anodes" width="800" height="600" class="w-full h-full object-contain" decoding="async" loading="lazy">\n            </div>\n        </div>\n    </div>\n',
