        html: '\n    <div data-mmo-container="page" class="w-full max-w-7xl mx-auto px-5 sm:px-6 lg:px-8">\n        <div class="max-w-3xl mb-12">\n            <span class="text-sm font-semibold tracking-wider uppercase text-blue-600 mb-2 block">APPLICATION &amp; INSTALLATION</span>\n            <h2 class="text-3xl md:text-4xl font-bold text-gray-900 leading-tight mb-4">Where MMO Rod Anodes Are Used</h2>\n        </div>\n\n        <div class="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10 lg:grid-cols-4">\n            <div class="bg-white p-6 md:p-8 rounded-2xl border border-gray-200 shadow-sm">\n                <h3 class="text-xl font-semibold text-gray-900 mb-3">Compact ICCP Systems</h3>\n                <p class="text-base text-gray-600 leading-relaxed">\n                    Rigid solid-rod geometry can be used where the cathodic-protection design requires a compact active electrode and controlled mounting position.\n                </p>\n            </div>\n            <div class="bg-white p-6 md:p-8 rounded-2xl border border-gray-200 shadow-sm">\n                <h3 class="text-xl font-semibold text-gray-900 mb-3">Freshwater &amp; Water Equipment</h3>\n                <p class="text-base text-gray-600 leading-relaxed">\n                    MMO rod electrodes can be reviewed for suitable freshwater, condenser, chiller and water-side protection applications according to conductivity, chemistry, flow and required electrical duty.\n                </p>\n            </div>\n            <div class="bg-white p-6 md:p-8 rounded-2xl border border-gray-200 shadow-sm">\n                <h3 class="text-xl font-semibold text-gray-900 mb-3">Seawater &amp; Brackish Water</h3>\n                <p class="text-base text-gray-600 leading-relaxed">\n                    Project-specific rod configurations can be reviewed for appropriate marine or brackish-water applications when coating, current density, cable construction, sealing and mounting are matched to the environment.\n                </p>\n            </div>\n            <div class="bg-white p-6 md:p-8 rounded-2xl border border-gray-200 shadow-sm">\n                <h3 class="text-xl font-semibold text-gray-900 mb-3">Soil &amp; Conductive Backfill</h3>\n                <p class="text-base text-gray-600 leading-relaxed">\n                    Cable-connected rod configurations can be reviewed for appropriate soil or carbonaceous-backfill applications according to resistivity, required current, installation geometry and the CP system design.\n                </p>\n            </div>\n        </div>\n\n        <div class="bg-white border border-gray-200 rounded-xl p-5 flex flex-wrap gap-x-6 gap-y-3 items-center justify-center text-sm font-medium text-gray-600 shadow-sm">\n            <span class="text-gray-600">Installation Input:</span>\n            <span>Rod Placement</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Active-Area Exposure</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Electrode Spacing</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Mounting</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Environment Contact</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Cable / Terminal</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Mechanical Protection</span>\n            <span class="w-1 h-1 bg-gray-300 rounded-full"></span>\n            <span>Inspection Access</span>\n        </div>\n    </div>\n',
